class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = int(s, 2)
        from collections import deque

        visited = set()
        queue = deque()
        queue.append((1, 0))
        visited.add(1)
        count = 0

        while queue:
            current, steps = queue.popleft()
            if current < n and steps <= k:
                count += 1
            if steps >= k:
                continue

            def generate_numbers_with_c_bits(c):
                n_str = bin(n)[2:]
                result = []

                def backtrack(pos, current_bits, tight, set_count):
                    if pos == len(n_str):
                        if set_count == c:
                            num = int(current_bits, 2)
                            if num < n:
                                result.append(num)
                        return

                    if tight:
                        max_bit = int(n_str[pos])
                        for bit in [0, 1]:
                            if bit > max_bit:
                                continue
                            new_tight = tight and (bit == max_bit)
                            new_set_count = set_count + (bit == 1)
                            backtrack(pos + 1, current_bits + str(bit), new_tight, new_set_count)
                    else:
                        for bit in [0, 1]:
                            new_set_count = set_count + (bit == 1)
                            backtrack(pos + 1, current_bits + str(bit), False, new_set_count)

                for length in range(1, len(n_str)):
                    if c > length:
                        continue
                    from itertools import combinations
                    for bits in combinations(range(length), c):
                        binary_str = ['0'] * length
                        for pos in bits:
                            binary_str[pos] = '1'
                        num = int(''.join(binary_str), 2)
                        if num < n:
                            result.append(num)

                backtrack(0, '', True, 0)
                result = list(set(result))
                return result

            generated = generate_numbers_with_c_bits(current)
            for y in generated:
                if y not in visited:
                    visited.add(y)
                    queue.append((y, steps + 1))

        return count % MOD
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        max_m = 800

        # Precompute steps for each m from 1 to max_m
        steps = [0] * (max_m + 1)
        for m in range(2, max_m + 1):
            bit_count = bin(m).count('1')
            steps[m] = 1 + steps[bit_count]

        total = 0
        for m in range(1, max_m + 1):
            if steps[m] > k - 1:
                continue
            count = self.compute_count_less(s, m, L, MOD)
            total = (total + count) % MOD

        return total

    def compute_count_less(self, s, m, L, MOD):
        # Initialize DP table: tight (0 or 1), count (0..m), has_set (0 or 1)
        dp_prev = [[[0] * 2 for _ in range(m + 1)] for _ in range(2)]
        dp_prev[1][0][0] = 1  # Initially, tight is 1, count is 0, no set bits

        for pos in range(L):
            dp_next = [[[0] * 2 for _ in range(m + 1)] for _ in range(2)]
            current_bit = int(s[pos])

            for tight in [0, 1]:
                for cnt in range(m + 1):
                    for has_set in [0, 1]:
                        if dp_prev[tight][cnt][has_set] == 0:
                            continue
                        max_bit = current_bit if tight else 1
                        for bit in range(0, max_bit + 1):
                            new_tight = 1 if (tight and (bit == current_bit)) else 0
                            new_cnt = cnt + (bit == 1)
                            new_has_set = 1 if (has_set or (bit == 1)) else 0
                            if new_cnt > m:
                                continue
                            dp_next[new_tight][new_cnt][new_has_set] = (dp_next[new_tight][new_cnt][new_has_set] + dp_prev[tight][cnt][has_set]) % MOD
            dp_prev = dp_next

        return (dp_prev[0][m][1] + dp_prev[1][m][1]) % MOD

