class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        max_bits = len(s)

        memo_steps = {}

        def get_steps(y):
            if y == 1:
                return 0
            if y in memo_steps:
                return memo_steps[y]
            cnt = bin(y).count('1')
            res = 1 + get_steps(cnt)
            memo_steps[y] = res
            return res

        steps = [0] * (max_bits + 2)  # steps[0] unused
        for y in range(1, max_bits + 2):
            steps[y] = get_steps(y)

        def count_less_than_n(s_str, y):
            s_list = [int(c) for c in s_str]
            n = len(s_list)

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, count, leading_zero):
                if pos == n:
                    return 1 if (not tight and count == y) else 0
                res = 0
                max_bit = s_list[pos] if tight else 1
                for bit in [0, 1]:
                    if bit > max_bit:
                        continue
                    new_tight = tight and (bit == max_bit)
                    new_leading_zero = leading_zero and (bit == 0)
                    new_count = count
                    if not new_leading_zero:
                        new_count = count + (1 if bit == 1 else 0)
                    res += dp(pos + 1, new_tight, new_count, new_leading_zero)
                return res

            return dp(0, True, 0, True)

        total = 0

        # Check if n is 1, which means there are no numbers less than n
        if s == '1':
            return 0

        # Add x=1 if it is less than n
        total += 1

        # Add numbers with y=1 if k >=1
        if k >= 1:
            cnt_y1 = count_less_than_n(s, 1)
            total += (cnt_y1 - 1)

        # Add numbers with y >=2 and steps[y] <=k-1
        for y in range(2, max_bits + 1):
            if steps[y] <= k - 1:
                cnt = count_less_than_n(s, y)
                total += cnt

        return total % MOD

