class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        adj = [[] for _ in range(n)]
        for u, v, length in edges:
            adj[u].append((v, length))
            adj[v].append((u, length))

        max_len = 0
        min_nodes = 0

        def dfs(node, parent, value_count, current_length, current_node_count):
            nonlocal max_len, min_nodes
            # Check if the current node's value is already in the path
            if nums[node] in value_count and value_count[nums[node]] > 0:
                # Cannot add this node to the path, so process children
                current_max = 0
                current_min = 1
                for child, edge_len in adj[node]:
                    if child != parent:
                        child_max, child_min = dfs(child, node, value_count, current_length, current_node_count)
                        if child_max > current_max:
                            current_max = child_max
                            current_min = child_min
                        elif child_max == current_max:
                            current_min = min(current_min, child_min)
                return current_max, current_min
            else:
                # Add the current node's value to the value_count
                value_count[nums[node]] = value_count.get(nums[node], 0) + 1
                # The current path is valid, calculate the max length and min nodes
                current_max = current_length
                current_min = current_node_count
                for child, edge_len in adj[node]:
                    if child != parent:
                        child_max, child_min = dfs(child, node, value_count, current_length + edge_len, current_node_count + 1)
                        if child_max + edge_len > current_max:
                            current_max = child_max + edge_len
                            current_min = child_min + 1
                        elif child_max + edge_len == current_max:
                            current_min = min(current_min, child_min + 1)
                # Backtrack
                value_count[nums[node]] -= 1
                return current_max, current_min

        # Initial call: root is 0, parent is -1, value_count is empty, current_length is 0, current_node_count is 1
        value_count = defaultdict(int)
        result_max, result_min = dfs(0, -1, value_count, 0, 1)
        return [result_max, result_min]
