class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        # Initialize the first pair (k=0)
        prev_dp = {}
        for color_i in range(3):
            for color_j in range(3):
                if color_i != color_j:
                    total_cost = cost[0][color_i] + cost[n-1][color_j]
                    prev_dp[(color_i, color_j)] = total_cost

        # Process the remaining pairs
        for k in range(1, m):
            current_dp = {}
            for (prev_i, prev_j), prev_cost in prev_dp.items():
                for color_i in range(3):
                    if color_i == prev_i:
                        continue
                    for color_j in range(3):
                        if color_j == prev_j:
                            continue
                        if color_i == color_j:
                            continue
                        # Calculate the cost for the current pair
                        current_cost = prev_cost + cost[k][color_i] + cost[n-1 - k][color_j]
                        key = (color_i, color_j)
                        if key not in current_dp or current_cost < current_dp[key]:
                            current_dp[key] = current_cost
            prev_dp = current_dp

        return min(prev_dp.values())
